from collections import Counter, deque

def transform(grid):
    h, w = len(grid), len(grid[0])
    background = Counter(v for row in grid for v in row).most_common(1)[0][0]
    seen = set()
    out = [row[:] for row in grid]
    for r in range(h):
        for c in range(w):
            if grid[r][c] != background or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            cells = []
            touches_edge = False
            while q:
                y, x = q.popleft()
                cells.append((y, x))
                if y == 0 or x == 0 or y == h - 1 or x == w - 1:
                    touches_edge = True
                for dy, dx in ((1, 0), (-1, 0), (0, 1), (0, -1)):
                    ny, nx = y + dy, x + dx
                    if 0 <= ny < h and 0 <= nx < w and grid[ny][nx] == background and (ny, nx) not in seen:
                        seen.add((ny, nx))
                        q.append((ny, nx))
            if not touches_edge:
                left = min(x for y, x in cells)
                right = max(x for y, x in cells)
                fill = 7 if (right - left + 1) % 2 else 2
                for y, x in cells:
                    out[y][x] = fill
    return out

